#include <stdbool.h>

/* A helper return exits both loops at once. */
bool find_empty(int seats[3][3], int *row, int *col) {
    for (int r = 0; r < 3; r++) {
        for (int c = 0; c < 3; c++) {
            if (seats[r][c] == 0) {
                *row = r;
                *col = c;
                return true;      /* leaves the function: both loops done. */
            }
        }
    }
    return false;
}

/* continue: skip invalid entries, keep looping. */
int sum_positive(const int *v, size_t n) {
    int sum = 0;
    for (size_t i = 0; i < n; i++) {
        if (v[i] < 0) continue;   /* i++ still runs. */
        sum += v[i];
    }
    return sum;
}
```

| Statement | Leaves |
|---|---|
| `break`. | nearest loop or switch. |
| `continue`. | current iteration of the nearest loop. |
| `return`. | the whole function. |
| `goto`. | to a label in the same function. |

